using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>() returned metadata for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// This will succeed — the default resolver can handle Person.
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
{
    Console.WriteLine($"\nTryGetTypeInfo<Person> succeeded: {found!.Type.Name}");
}

// Create restricted options with an empty custom resolver so that
// Stream metadata is *not* available.
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers =
        {
            ti =>
            {
                // Reject everything except Person
                if (ti.Type != typeof(Person))
                    throw new NotSupportedException($"{ti.Type.Name} is not allowed");
            }
        }
    }
};

if (restricted.TryGetTypeInfo<Stream>(out JsonTypeInfo<Stream>? streamInfo))
{
    Console.WriteLine($"TryGetTypeInfo<Stream> succeeded (unexpected): {streamInfo!.Type.Name}");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo<Stream> returned false — no exception thrown.");
}

// Record used by the examples above
public record Person(string Name, int Age);

